import dotenv from 'dotenv';
dotenv.config();

const uri = process.env.DOCUMENTDB_URI;
if (!uri) {
  console.error('Missing DOCUMENTDB_URI in environment');
}

let client = null;
let clientPromise = null;

export function getClient() {
  if (client) return client;
  if (!clientPromise) {
    clientPromise = MongoClient.connect(uri, {
      // DocumentDB requires TLS; trust the environment-provided string
      // Keep default pool sizes; users can tune via env if needed.
      useNewUrlParser: true,
      useUnifiedTopology: true
    }).then(c => {
      client = c;
      return client;
    });
  }
  throw new Error('Client not initialized synchronously; use getClientAsync');
}

export async function getClientAsync() {
  if (client) return client;
  if (!clientPromise) {
    clientPromise = MongoClient.connect(uri, {
      useNewUrlParser: true,
      useUnifiedTopology: true
    }).then(c => {
      client = c;
      return client;
    });
  }
  return clientPromise;
}

export function getDb() {
  if (!client) throw new Error('Client not connected; call getClientAsync first');
  const dbName = process.env.DB_NAME || 'sample_retail_12';
  return client.db(dbName);
}

export async function closeClient() {
  if (client) {
    await client.close();
    client = null;
    clientPromise = null;
  }
}
"}

