{"path": "src/copyAgent.js", "content": "import dotenv from 'dotenv';
dotenv.config();
import { ChatOpenAI } from 'langchain/chat_models/openai';
import { HumanChatMessage, SystemChatMessage } from 'langchain/schema';

const openaiKey = process.env.OPENAI_API_KEY;
if (!openaiKey) {
  console.warn('OPENAI_API_KEY not set: copyAgent will fail if invoked.');
}

const client = new ChatOpenAI({ openAIApiKey: openaiKey, temperature: 0.7 });

export async function generateRecoveryMessage(cart, customer) {
  // Compose a short prompt to create a personalized recovery message
  const system = new SystemChatMessage('You are a friendly e-commerce retention assistant producing brief personalised cart-recovery messages. Keep it under 120 words.');
  const userParts = [];
  userParts.push(`Customer name: ${customer.name}`);
  userParts.push(`Cart total: $${cart.total}`);
  userParts.push(`Items: ${cart.items.map(i => `${i.qty}x ${i.name}`).join(', ')}`);
  userParts.push('Goal: write a short, persuasive, personal message encouraging purchase, including a small incentive (e.g., 10% off) and clear CTA.');
  const user = new HumanChatMessage(userParts.join('\n'));

  const resp = await client.call([system, user]);
  const text = resp.text?.trim();
  return text || `Hi ${customer.name}, we noticed you left items in your cart. Come back to complete your purchase!`;
}
"}

